        "tree": [
          {
            "path": "app/api/assistant/stream/route.ts",
            "purpose": "POST SSE endpoint; validates input, owns HTTP headers, request abort handling, idle watchdog, stream event encoding, and committed-header failure behavior."
          },
          {
            "path": "src/application/assistant/generate.ts",
